package com.vibeguard.samples.twofactor; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Checks a configured demonstration second factor behind service authentication. */ @RestController @RequestMapping("/internal/two-factor") public class TwoFactorController { @Value("${TWO_FACTOR_SERVICE_KEY:}") private String serviceKey; @Value("${TWO_FACTOR_DEMO_CODE:}") private String expectedCode; @PostMapping("/verify") public ResponseEntity<Result> verify(@RequestHeader("X-Two-Factor-Service-Key") String key,@Valid @RequestBody Request request){if(!allowed(key))return ResponseEntity.status(401).build();boolean valid=!expectedCode.isBlank()&&MessageDigest.isEqual(expectedCode.getBytes(StandardCharsets.UTF_8),request.code().getBytes(StandardCharsets.UTF_8));return ResponseEntity.ok(new Result(request.userId(),valid));}private boolean allowed(String key){return !serviceKey.isBlank()&&MessageDigest.isEqual(serviceKey.getBytes(StandardCharsets.UTF_8),key.getBytes(StandardCharsets.UTF_8));}record Request(@NotBlank String userId,@NotBlank String code){}record Result(String userId,boolean valid){} }
